import { inject } from 'inversify';
import { TYPES } from '@src/di/types/types';
import { Query } from '@src/domain/models/query';
import { type IDepositAccountRepository } from '@src/domain/interfaces/loan_collateral/depositAccount';
import { DepositAccountPayload } from './depositAccount_query';

export class DepositAccountHandler {
    private readonly _repository: IDepositAccountRepository;

    constructor(
        @inject(TYPES.IDepositAccountRepository)
        depositAccountRepository: IDepositAccountRepository,
    ) {
        this._repository = depositAccountRepository;
    }

    handler(query: Query<DepositAccountPayload>) {
        return this._repository.getListDepositAccounts(query);
    }
}
