import { payloadConfig } from './../../../utils/common';
import { createAsyncThunk } from '@reduxjs/toolkit';
import { DepositAccountHandler } from '@src/application/loan_collateral/getListDepositAccounts/depositAccount_handler';
import { DepositAccountPayload } from '@src/application/loan_collateral/getListDepositAccounts/depositAccount_query';
import { container } from '@src/di/inversify.config';
import { TYPES } from '@src/di/types/types';
import { Query } from '@src/domain/models/query';
import { commonService } from '@src/infrastructure/network/networkService';

export const getListDepositAccounts = createAsyncThunk('loan_collateral/getListDepositAccounts', async (request: DepositAccountPayload['data']) => {
    const depositAccounts = container.get<DepositAccountHandler>(TYPES.DepositAccountHandler);
    // const payload = {
    //     ...payloadConfig,
    //     data: request,
    // };
    const payload = commonService.getPayload<DepositAccountPayload, DepositAccountPayload['data']>({ data: request });
    const query = new Query<DepositAccountPayload>({
        query: payload,
    });

    return depositAccounts.handler(query);
});
