import { createSlice } from '@reduxjs/toolkit';
import { fetchClientInfo } from './thunk';
import type { ClientInfo } from '@src/domain/entities/common/clientInfo';
import { UserInfo } from '@src/domain/entities/userInfo';

interface IState {
    status: 'idle' | 'loading' | 'succeeded' | 'failed';
    error: string;
    queue: Record<string, string>;
    data: {
        clientInfo: ClientInfo['data'];
    };
    flow: string;
    userInfo: UserInfo;
    token: string;
}

const initialState: IState = {
    status: 'idle',
    error: '',
    queue: {},
    data: {
        clientInfo: {
            clientNo: '',
            clientName: '',
            clientType: '',
            location: {} as ClientInfo['data']['location'],
            globalIdType: '',
            globalId: '',
            dtOfIssuance: '',
            placeOfIssuance: '',
            birthDate: '',
            phoneNumber: '',
            emailAddress: '',
            sex: '',
            countryDesc: '',
            expiryDate: '',
        },
    },
    flow: '',
    userInfo: { clientNo: '' } as UserInfo,
    token: '',
};

export const ProductSlice = createSlice({
    name: 'loan_products',
    initialState,
    reducers: {
        resetClientInfo: (state) => {
            state.data.clientInfo = {} as ClientInfo['data'];
        },
        updateFlow: (state, action) => {
            state.flow = action.payload;
        },
        updateUserInfo: (state, action) => {
            state.userInfo = action.payload;
        },
        updateToken: (state, action) => {
            state.token = action.payload;
        },
        setError: (state, { payload }) => {
            state.error = payload;
        },
    },
    extraReducers: (builder) => {
        builder
            .addCase(fetchClientInfo.pending, (state) => {
                state.status = 'loading';
                state.queue.getClientInfo = 'getClientInfo';
            })
            .addCase(fetchClientInfo.rejected, (state, action) => {
                delete state.queue.getClientInfo;
                if (Object.keys(state.queue).length === 0) {
                    state.status = 'failed';
                }
                state.error = action.error.message ?? 'Failed to fetch loan register';
            })
            .addCase(fetchClientInfo.fulfilled, (state, action) => {
                delete state.queue.getClientInfo;
                if (Object.keys(state.queue).length === 0) {
                    state.status = 'succeeded';
                }
                const { data, resultCode, resultMessage } = action.payload;
                if (resultCode === '00' && data) {
                    state.data.clientInfo = action.payload.data;
                } else {
                    state.error = resultMessage;
                }
            });
    },
});
