import { ReduxState } from '@src/lib/redux';

export const selectClientInfo = (state: ReduxState) => state.product?.data?.clientInfo;
export const selectClientType = (state: ReduxState) => state.product?.data?.clientInfo?.clientType;
export const selectClientNo = (state: ReduxState) => state.product?.userInfo?.clientNo;
export const selectStatus = (state: ReduxState) => state.product?.status || '';
export const selectError = (state: ReduxState) => state.product?.error;
export const selectFlow = (state: ReduxState) => state.product?.flow;
export const selectUserInfo = (state: ReduxState) => state.product?.userInfo;
export const selectToken = (state: ReduxState) => state.product?.token;